function validate([nums1, nums2]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  if (nums1.length !== nums2.length) return 'nums1 and nums2 need the same length.';
  if (nums1.length < 1 || nums1.length > 1e5) return 'The arrays hold 1 to 10^5 values.';
  const ok = v => Number.isInteger(v) && v >= 1 && v <= 1e5;
  if (!nums1.every(ok) || !nums2.every(ok)) return 'Every value is an integer from 1 to 10^5.';
  return null;
}

