function minAbsoluteSumDiff(nums1, nums2) {
  const MOD = 1_000_000_007;
  const sorted = [...nums1].sort((a, b) => a - b);
  let total = 0;
  let bestGain = 0;

  for (let i = 0; i < nums1.length; i++) {
    const diff = Math.abs(nums1[i] - nums2[i]);
    total += diff;

    let left = 0;
    let right = sorted.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (sorted[mid] < nums2[i]) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }

    let closest = diff;
    if (left < sorted.length) {
      closest = Math.min(closest, sorted[left] - nums2[i]);
    }
    if (left > 0) {
      closest = Math.min(closest, nums2[i] - sorted[left - 1]);
    }
    bestGain = Math.max(bestGain, diff - closest);
  }
  return (total - bestGain) % MOD;
}

