function minAbsoluteSumDiff(nums1, nums2) {
  // Try every replacement (position i takes the value at position j) and keep the smallest total.
  const n = nums1.length;
  let base = 0;
  for (let i = 0; i < n; i++) base += Math.abs(nums1[i] - nums2[i]);
  let best = base;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const changed = base - Math.abs(nums1[i] - nums2[i]) + Math.abs(nums1[j] - nums2[i]);
      if (changed < best) best = changed;
    }
  }
  return best % 1000000007;
}

